import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CHeM0PsO.js";const d=JSON.parse('{"title":"Authentication","description":"","frontmatter":{"title":"Authentication"},"headers":[],"relativePath":"concepts/authentication.md","filePath":"concepts/authentication.md"}'),o={name:"concepts/authentication.md"};function r(n,e,c,l,h,u){return t(),s("div",null,[...e[0]||(e[0]=[i('<blockquote><p>🚧 Wingport is in active development. The API described here is the v0.1 design. Star the repo to follow along, or join the early access list.</p></blockquote><h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h1><p>Wingport does not have its own auth system — that&#39;s the point. It authenticates every request with the session your users already have.</p><h2 id="supabase" tabindex="-1">Supabase <a class="header-anchor" href="#supabase" aria-label="Permalink to &quot;Supabase&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">provider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;supabase&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>The Dart SDK attaches the current session&#39;s access token to every request. The gateway verifies it locally using your project&#39;s JWT secret. Expired token → <code>401</code> → the SDK surfaces <code>AuthException</code> (and will retry once after <code>supabase_flutter</code> refreshes the session).</p><p>The verified user ID (<code>sub</code> claim) becomes the identity for quotas and usage metering.</p><h2 id="anonymous-users" tabindex="-1">Anonymous users <a class="header-anchor" href="#anonymous-users" aria-label="Permalink to &quot;Anonymous users&quot;">​</a></h2><p>If your app supports Supabase anonymous sign-ins, set <code>allowAnonymous: true</code>. Anonymous users get their own quota rows — useful for try-before-signup flows, with limits keeping abuse bounded.</p><h2 id="firebase-planned" tabindex="-1">Firebase <span class="VPBadge warning">Planned</span> <a class="header-anchor" href="#firebase-planned" aria-label="Permalink to &quot;Firebase &lt;span class=&quot;VPBadge warning&quot;&gt;Planned&lt;/span&gt;&quot;">​</a></h2><p><code>auth: { provider: &quot;firebase&quot; }</code> will verify Firebase ID tokens, enabling Firebase-auth apps to use a Wingport gateway.</p><h2 id="service-calls-server-to-server" tabindex="-1">Service calls (server-to-server) <a class="header-anchor" href="#service-calls-server-to-server" aria-label="Permalink to &quot;Service calls (server-to-server)&quot;">​</a></h2><p>For trusted server contexts (cron jobs, admin scripts), mint a service token with the CLI: <code>wingport token create --role service</code>. Service calls bypass per-user limits but are still metered.</p><hr>',14)])])}const b=a(o,[["render",r]]);export{d as __pageData,b as default};
